Use ASP.NET Core's **`WebApplicationFactory<TEntryPoint>`** from `Microsoft.AspNetCore.Mvc.Testing`. It hosts your app in-memory — no real ports, no real server.

### Setup

```bash
dotnet add package Microsoft.AspNetCore.Mvc.Testing
```

### Example test (xUnit)

```csharp
public class McpIntegrationTests : IClassFixture<WebApplicationFactory<Program>>
{
    private readonly HttpClient _client;

    public McpIntegrationTests(WebApplicationFactory<Program> factory)
    {
        _client = factory.CreateClient();
    }

    [Fact]
    public async Task Initialize_ReturnsServerCapabilities()
    {
        var request = new
        {
            jsonrpc = "2.0",
            id = 1,
            method = "initialize",
            @params = new
            {
                protocolVersion = "2025-03-26",
                capabilities = new { },
                clientInfo = new { name = "test-client", version = "1.0" }
            }
        };

        var response = await _client.PostAsJsonAsync("/mcp", request);

        response.EnsureSuccessStatusCode();
        var body = await response.Content.ReadFromJsonAsync<JsonElement>();
        Assert.Equal("2.0", body.GetProperty("jsonrpc").GetString());
        Assert.Equal(1, body.GetProperty("id").GetInt32());
        Assert.True(body.GetProperty("result").TryGetProperty("capabilities", out _));
    }

    [Fact]
    public async Task ToolsList_ReturnsRegisteredTools()
    {
        // Initialize first (stateful session via Mcp-Session-Id header)
        var initResp = await _client.PostAsJsonAsync("/mcp", new
        {
            jsonrpc = "2.0", id = 1, method = "initialize",
            @params = new { protocolVersion = "2025-03-26",
                            capabilities = new { },
                            clientInfo = new { name = "test", version = "1.0" } }
        });
        var sessionId = initResp.Headers.GetValues("Mcp-Session-Id").First();

        // Call tools/list with session header
        var req = new HttpRequestMessage(HttpMethod.Post, "/mcp")
        {
            Content = JsonContent.Create(new
            {
                jsonrpc = "2.0", id = 2, method = "tools/list"
            })
        };
        req.Headers.Add("Mcp-Session-Id", sessionId);

        var resp = await _client.SendAsync(req);
        resp.EnsureSuccessStatusCode();

        var body = await resp.Content.ReadFromJsonAsync<JsonElement>();
        var tools = body.GetProperty("result").GetProperty("tools");
        Assert.True(tools.GetArrayLength() > 0);
    }
}
```

### Key points

- **`WebApplicationFactory`** uses your real `Program`/`Startup` — full middleware pipeline, DI, routing all run in-process.
- **No ports or processes** — `CreateClient()` returns an `HttpClient` wired to an in-memory `TestServer`.
- **Override services** with `.WithWebHostBuilder(b => b.ConfigureServices(...))` to swap in mocks (e.g., fake databases).
- If your server uses **SSE streaming**, read the response stream incrementally with `HttpCompletionOption.ResponseHeadersRead` and parse `text/event-stream` lines.
- Make sure `Program` is accessible (add `InternalsVisibleTo` or a `public partial class Program { }` marker).
